const cardsData = [{"filename": "card-ice-slider.html", "title": "Frozen Ice Multi-Card Carousel Slider", "description": "Ultra-modern multi-card responsive carousel featuring frozen ice frosted glassmorphic styling, refraction gloss sheen, smooth sliding controls, and touch swipe gestures.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Frozen Ice Multi-Card Carousel Slider</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --ice-primary: #a5f3fc;\n      --ice-glow: rgba(56, 189, 248, 0.45);\n      --ice-crystal: rgba(224, 242, 254, 0.85);\n      --ice-border: rgba(255, 255, 255, 0.35);\n      --ice-card-bg: rgba(255, 255, 255, 0.08);\n      --frost-shadow: 0 20px 45px -10px rgba(14, 165, 233, 0.3);\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n    }\n\n    body {\n      font-family: 'Plus Jakarta Sans', sans-serif;\n      min-height: 100vh;\n      background: radial-gradient(circle at 50% 20%, #0d2847 0%, #071526 60%, #030a13 100%);\n      color: #f0f9ff;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      padding: 2.5rem 1.5rem;\n      position: relative;\n      overflow-x: hidden;\n    }\n\n    /* Floating Frost Auroras & Ice Ambient Glows */\n    .aurora-bg {\n      position: absolute;\n      top: -15%;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 800px;\n      height: 500px;\n      background: radial-gradient(ellipse at center, rgba(56, 189, 248, 0.18) 0%, rgba(14, 165, 233, 0.08) 50%, transparent 70%);\n      filter: blur(80px);\n      pointer-events: none;\n      z-index: 0;\n    }\n\n    .header-section {\n      text-align: center;\n      margin-bottom: 2.5rem;\n      z-index: 1;\n      max-width: 650px;\n    }\n\n    .ice-tag {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      padding: 6px 14px;\n      background: rgba(186, 230, 253, 0.12);\n      border: 1px solid rgba(186, 230, 253, 0.35);\n      border-radius: 9999px;\n      font-size: 0.78rem;\n      font-weight: 700;\n      letter-spacing: 1.5px;\n      text-transform: uppercase;\n      color: #bae6fd;\n      backdrop-filter: blur(8px);\n      box-shadow: 0 0 20px rgba(56, 189, 248, 0.25);\n      margin-bottom: 12px;\n    }\n\n    .header-section h1 {\n      font-size: 2.4rem;\n      font-weight: 800;\n      color: #ffffff;\n      text-shadow: 0 0 35px rgba(186, 230, 253, 0.6), 0 2px 4px rgba(0,0,0,0.5);\n      margin-bottom: 8px;\n      letter-spacing: -0.5px;\n    }\n\n    .header-section p {\n      color: #93c5fd;\n      font-size: 0.95rem;\n      line-height: 1.5;\n    }\n\n    /* Slider Container */\n    .slider-wrapper {\n      position: relative;\n      width: 100%;\n      max-width: 1280px;\n      z-index: 1;\n      display: flex;\n      align-items: center;\n    }\n\n    .slider-viewport {\n      width: 100%;\n      overflow: hidden;\n      padding: 24px 8px 36px;\n      border-radius: 28px;\n    }\n\n    .slider-track {\n      display: flex;\n      gap: 24px;\n      transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);\n      will-change: transform;\n    }\n\n    /* Frosted Ice Glass Card */\n    .ice-card {\n      flex: 0 0 calc((100% - (24px * 2)) / 3);\n      min-width: 290px;\n      background: var(--ice-card-bg);\n      border: 1px solid var(--ice-border);\n      border-top: 1px solid rgba(255, 255, 255, 0.6);\n      border-left: 1px solid rgba(255, 255, 255, 0.45);\n      border-radius: 24px;\n      padding: 24px 22px;\n      backdrop-filter: blur(24px);\n      -webkit-backdrop-filter: blur(24px);\n      box-shadow: var(--frost-shadow), inset 0 0 25px rgba(255, 255, 255, 0.05);\n      display: flex;\n      flex-direction: column;\n      position: relative;\n      overflow: hidden;\n      transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);\n      cursor: pointer;\n    }\n\n    /* Refractive Ice Gloss Sheen */\n    .ice-card::before {\n      content: '';\n      position: absolute;\n      top: 0;\n      left: 0;\n      right: 0;\n      height: 45%;\n      background: linear-gradient(180deg, rgba(255, 255, 255, 0.22) 0%, rgba(255, 255, 255, 0.02) 100%);\n      border-radius: 24px 24px 80px 80px;\n      pointer-events: none;\n    }\n\n    /* Frost Ice Crystals Particle Overlay */\n    .ice-card::after {\n      content: '';\n      position: absolute;\n      inset: 0;\n      border-radius: 24px;\n      box-shadow: inset 0 0 35px rgba(125, 211, 252, 0.15);\n      pointer-events: none;\n      transition: opacity 0.3s ease;\n    }\n\n    .ice-card:hover {\n      transform: translateY(-8px) scale(1.02);\n      border-color: rgba(255, 255, 255, 0.7);\n      box-shadow: 0 25px 50px -10px rgba(56, 189, 248, 0.5), inset 0 0 30px rgba(255, 255, 255, 0.15);\n    }\n\n    /* Card Elements */\n    .card-top {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      margin-bottom: 18px;\n      position: relative;\n      z-index: 2;\n    }\n\n    .ice-icon {\n      width: 48px;\n      height: 48px;\n      border-radius: 14px;\n      background: rgba(255, 255, 255, 0.14);\n      border: 1px solid rgba(255, 255, 255, 0.4);\n      backdrop-filter: blur(10px);\n      display: grid;\n      place-items: center;\n      font-size: 22px;\n      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);\n    }\n\n    .temp-pill {\n      font-family: 'JetBrains Mono', monospace;\n      font-size: 0.75rem;\n      font-weight: 700;\n      padding: 4px 10px;\n      border-radius: 20px;\n      background: rgba(14, 165, 233, 0.25);\n      border: 1px solid rgba(125, 211, 252, 0.4);\n      color: #e0f2fe;\n    }\n\n    .card-media {\n      width: 100%;\n      height: 160px;\n      border-radius: 16px;\n      object-fit: cover;\n      margin-bottom: 16px;\n      border: 1px solid rgba(255, 255, 255, 0.2);\n      box-shadow: 0 8px 20px rgba(0,0,0,0.3);\n      position: relative;\n      z-index: 2;\n    }\n\n    .card-title {\n      font-size: 1.25rem;\n      font-weight: 700;\n      color: #ffffff;\n      margin-bottom: 6px;\n      position: relative;\n      z-index: 2;\n    }\n\n    .card-desc {\n      font-size: 0.85rem;\n      color: #bfdbfe;\n      line-height: 1.5;\n      margin-bottom: 20px;\n      flex: 1;\n      position: relative;\n      z-index: 2;\n    }\n\n    .card-footer {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding-top: 14px;\n      border-top: 1px solid rgba(255, 255, 255, 0.15);\n      position: relative;\n      z-index: 2;\n    }\n\n    .ice-stat {\n      display: flex;\n      flex-direction: column;\n    }\n\n    .stat-label {\n      font-size: 0.7rem;\n      color: #7dd3fc;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      font-weight: 600;\n    }\n\n    .stat-val {\n      font-family: 'JetBrains Mono', monospace;\n      font-size: 1.05rem;\n      font-weight: 700;\n      color: #ffffff;\n    }\n\n    .btn-ice {\n      padding: 8px 16px;\n      background: linear-gradient(135deg, rgba(255, 255, 255, 0.3) 0%, rgba(255, 255, 255, 0.1) 100%);\n      border: 1px solid rgba(255, 255, 255, 0.5);\n      color: #ffffff;\n      border-radius: 10px;\n      font-size: 0.82rem;\n      font-weight: 700;\n      cursor: pointer;\n      backdrop-filter: blur(12px);\n      transition: all 0.2s ease;\n      box-shadow: 0 4px 12px rgba(14, 165, 233, 0.25);\n    }\n\n    .btn-ice:hover {\n      background: rgba(255, 255, 255, 0.95);\n      color: #0369a1;\n      box-shadow: 0 6px 20px rgba(56, 189, 248, 0.6);\n    }\n\n    /* Slider Arrows */\n    .nav-arrow {\n      position: absolute;\n      top: 50%;\n      transform: translateY(-50%);\n      width: 52px;\n      height: 52px;\n      border-radius: 50%;\n      background: rgba(15, 23, 42, 0.65);\n      border: 1px solid rgba(255, 255, 255, 0.35);\n      backdrop-filter: blur(16px);\n      color: #e0f2fe;\n      display: grid;\n      place-items: center;\n      font-size: 22px;\n      cursor: pointer;\n      z-index: 10;\n      box-shadow: 0 8px 25px rgba(0,0,0,0.4);\n      transition: all 0.25s ease;\n    }\n\n    .nav-arrow:hover {\n      background: rgba(56, 189, 248, 0.35);\n      border-color: #ffffff;\n      color: #ffffff;\n      box-shadow: 0 0 25px rgba(56, 189, 248, 0.7);\n    }\n\n    .nav-arrow.prev { left: -26px; }\n    .nav-arrow.next { right: -26px; }\n\n    /* Slider Dots Indicators */\n    .slider-dots {\n      display: flex;\n      justify-content: center;\n      gap: 10px;\n      margin-top: 1.5rem;\n      z-index: 1;\n    }\n\n    .dot {\n      width: 10px;\n      height: 10px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.2);\n      border: 1px solid rgba(255, 255, 255, 0.3);\n      cursor: pointer;\n      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    .dot.active {\n      width: 28px;\n      border-radius: 9999px;\n      background: linear-gradient(90deg, #38bdf8, #bae6fd);\n      box-shadow: 0 0 15px rgba(56, 189, 248, 0.7);\n    }\n\n    /* Responsive Breakpoints */\n    @media (max-width: 1024px) {\n      .ice-card {\n        flex: 0 0 calc((100% - 24px) / 2);\n      }\n      .nav-arrow.prev { left: -14px; }\n      .nav-arrow.next { right: -14px; }\n    }\n\n    @media (max-width: 680px) {\n      .ice-card {\n        flex: 0 0 100%;\n      }\n      .header-section h1 {\n        font-size: 1.8rem;\n      }\n      .nav-arrow {\n        display: none;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"aurora-bg\"></div>\n\n  <div class=\"header-section\">\n    <div class=\"ice-tag\">\u2744\ufe0f Cryogenic Glass Design</div>\n    <h1>Glacial Multi-Card Carousel</h1>\n    <p>Frosted ice translucent cards sliding smoothly with multi-view perspective, refraction gloss, and ambient winter lighting.</p>\n  </div>\n\n  <div class=\"slider-wrapper\">\n    <button class=\"nav-arrow prev\" onclick=\"slidePrev()\" aria-label=\"Previous Cards\">&#10094;</button>\n\n    <div class=\"slider-viewport\" id=\"sliderViewport\">\n      <div class=\"slider-track\" id=\"sliderTrack\">\n\n        <!-- Card 1 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\ud83e\uddca</div>\n            <span class=\"temp-pill\">-18\u00b0C FROST</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1517411032315-54ef2cb783bb?w=600&auto=format&fit=crop&q=80\" alt=\"Glacier Cave\" />\n          <h3 class=\"card-title\">Glacier Cavern</h3>\n          <p class=\"card-desc\">Subterranean crystal formations preserved under centuries of Scandinavian pack ice.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Elevation</span>\n              <span class=\"stat-val\">2,480m</span>\n            </div>\n            <button class=\"btn-ice\">Explore</button>\n          </div>\n        </div>\n\n        <!-- Card 2 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\u2744\ufe0f</div>\n            <span class=\"temp-pill\">-25\u00b0C BOREALIS</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1531366936337-7c912a4589a7?w=600&auto=format&fit=crop&q=80\" alt=\"Aurora Borealis\" />\n          <h3 class=\"card-title\">Aurora Horizon</h3>\n          <p class=\"card-desc\">Atmospheric cyan luminescence reflecting across untouched polar ice sheets.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Intensity</span>\n              <span class=\"stat-val\">Kp 8.4</span>\n            </div>\n            <button class=\"btn-ice\">Observe</button>\n          </div>\n        </div>\n\n        <!-- Card 3 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\ud83d\udc8e</div>\n            <span class=\"temp-pill\">-32\u00b0C ARCTIC</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1483921020237-2ff51e8e4b22?w=600&auto=format&fit=crop&q=80\" alt=\"Crystal Ice\" />\n          <h3 class=\"card-title\">Diamond Permafrost</h3>\n          <p class=\"card-desc\">Ultra-dense translucent ice lenses exhibiting geometric hexagonal refraction.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Clarity</span>\n              <span class=\"stat-val\">99.8%</span>\n            </div>\n            <button class=\"btn-ice\">Analyze</button>\n          </div>\n        </div>\n\n        <!-- Card 4 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\ud83c\udfd4\ufe0f</div>\n            <span class=\"temp-pill\">-15\u00b0C SUMMIT</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?w=600&auto=format&fit=crop&q=80\" alt=\"Alpine Ridge\" />\n          <h3 class=\"card-title\">Alpine Needle</h3>\n          <p class=\"card-desc\">High-altitude ridge bathed in morning frost with winds reaching 80 km/h.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Altitude</span>\n              <span class=\"stat-val\">4,120m</span>\n            </div>\n            <button class=\"btn-ice\">Ascend</button>\n          </div>\n        </div>\n\n        <!-- Card 5 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\ud83c\udf28\ufe0f</div>\n            <span class=\"temp-pill\">-40\u00b0C POLAR</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1516715094483-75da7dee9758?w=600&auto=format&fit=crop&q=80\" alt=\"Polar Tundra\" />\n          <h3 class=\"card-title\">Polar Tundra</h3>\n          <p class=\"card-desc\">Endless horizon of pristine white drifts and crystalline silence under winter skies.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Wind Chill</span>\n              <span class=\"stat-val\">-54\u00b0C</span>\n            </div>\n            <button class=\"btn-ice\">Discover</button>\n          </div>\n        </div>\n\n        <!-- Card 6 -->\n        <div class=\"ice-card\">\n          <div class=\"card-top\">\n            <div class=\"ice-icon\">\ud83c\udf0c</div>\n            <span class=\"temp-pill\">-22\u00b0C FJORD</span>\n          </div>\n          <img class=\"card-media\" src=\"https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?w=600&auto=format&fit=crop&q=80\" alt=\"Frozen Fjord\" />\n          <h3 class=\"card-title\">Frozen Fjord Waters</h3>\n          <p class=\"card-desc\">Mirror-still saltwater ice reflecting towering cliffs and starry winter constellations.</p>\n          <div class=\"card-footer\">\n            <div class=\"ice-stat\">\n              <span class=\"stat-label\">Ice Depth</span>\n              <span class=\"stat-val\">1.8m</span>\n            </div>\n            <button class=\"btn-ice\">Voyage</button>\n          </div>\n        </div>\n\n      </div>\n    </div>\n\n    <button class=\"nav-arrow next\" onclick=\"slideNext()\" aria-label=\"Next Cards\">&#10095;</button>\n  </div>\n\n  <!-- Dots Navigation -->\n  <div class=\"slider-dots\" id=\"dotsContainer\"></div>\n\n  <script>\n    const track = document.getElementById('sliderTrack');\n    const cards = document.querySelectorAll('.ice-card');\n    const dotsContainer = document.getElementById('dotsContainer');\n    \n    let currentIndex = 0;\n\n    function getVisibleCount() {\n      if (window.innerWidth <= 680) return 1;\n      if (window.innerWidth <= 1024) return 2;\n      return 3;\n    }\n\n    function getMaxIndex() {\n      return Math.max(0, cards.length - getVisibleCount());\n    }\n\n    function updateSlider() {\n      const visible = getVisibleCount();\n      const maxIdx = getMaxIndex();\n      if (currentIndex > maxIdx) currentIndex = maxIdx;\n\n      const cardWidth = cards[0].offsetWidth;\n      const gap = 24;\n      const offset = currentIndex * (cardWidth + gap);\n      \n      track.style.transform = `translateX(-${offset}px)`;\n\n      renderDots();\n    }\n\n    function renderDots() {\n      dotsContainer.innerHTML = '';\n      const maxIdx = getMaxIndex();\n      const totalSteps = maxIdx + 1;\n\n      for (let i = 0; i < totalSteps; i++) {\n        const dot = document.createElement('div');\n        dot.className = `dot ${i === currentIndex ? 'active' : ''}`;\n        dot.onclick = () => {\n          currentIndex = i;\n          updateSlider();\n        };\n        dotsContainer.appendChild(dot);\n      }\n    }\n\n    function slideNext() {\n      const maxIdx = getMaxIndex();\n      if (currentIndex < maxIdx) {\n        currentIndex++;\n      } else {\n        currentIndex = 0; // loop back\n      }\n      updateSlider();\n    }\n\n    function slidePrev() {\n      const maxIdx = getMaxIndex();\n      if (currentIndex > 0) {\n        currentIndex--;\n      } else {\n        currentIndex = maxIdx; // loop forward\n      }\n      updateSlider();\n    }\n\n    // Touch and Drag swipe support\n    let startX = 0;\n    let isDragging = false;\n\n    track.addEventListener('touchstart', (e) => {\n      startX = e.touches[0].clientX;\n      isDragging = true;\n    }, { passive: true });\n\n    track.addEventListener('touchend', (e) => {\n      if (!isDragging) return;\n      const endX = e.changedTouches[0].clientX;\n      const diff = startX - endX;\n      if (diff > 50) slideNext();\n      else if (diff < -50) slidePrev();\n      isDragging = false;\n    });\n\n    window.addEventListener('resize', () => {\n      updateSlider();\n    });\n\n    // Initialize on load\n    updateSlider();\n  </script>\n</body>\n</html>\n"}, {"filename": "card1.html", "title": "3D Holographic Cyberpunk Card", "description": "Interactive 3D neon holographic tilt card with glowing border gradients and futuristic badges.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>3D Holographic Cyberpunk Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&family=JetBrains+Mono:wght@500&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #070913; min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n    .card { width: 340px; background: linear-gradient(135deg, rgba(255,255,255,0.05), rgba(255,255,255,0.01)); border: 1px solid rgba(255,255,255,0.1); border-radius: 20px; padding: 24px; position: relative; overflow: hidden; backdrop-filter: blur(16px); transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275); box-shadow: 0 15px 35px rgba(0,0,0,0.5); }\n    .card::before { content: ''; position: absolute; inset: -2px; border-radius: 22px; background: linear-gradient(45deg, #00f2fe, #4facfe, #000, #ff0844); z-index: -1; opacity: 0; transition: opacity 0.4s ease; }\n    .card:hover { transform: translateY(-8px) scale(1.02); }\n    .card:hover::before { opacity: 0.7; }\n    .card-img { width: 100%; height: 190px; border-radius: 14px; object-fit: cover; margin-bottom: 18px; }\n    .tag { font-family: 'JetBrains Mono', monospace; font-size: 0.75rem; color: #00f2fe; background: rgba(0,242,254,0.1); border: 1px solid rgba(0,242,254,0.25); padding: 4px 10px; border-radius: 6px; display: inline-block; margin-bottom: 10px; }\n    h3 { color: #fff; font-size: 1.25rem; font-weight: 800; margin-bottom: 8px; }\n    p { color: #94a3b8; font-size: 0.85rem; line-height: 1.5; margin-bottom: 20px; }\n    .card-footer { display: flex; justify-content: space-between; align-items: center; padding-top: 14px; border-top: 1px solid rgba(255,255,255,0.08); }\n    .author { display: flex; align-items: center; gap: 8px; color: #e2e8f0; font-size: 0.82rem; }\n    .author-img { width: 28px; height: 28px; border-radius: 50%; }\n    .price { font-family: 'JetBrains Mono', monospace; color: #38bdf8; font-weight: 700; font-size: 0.95rem; }\n  </style>\n</head>\n<body>\n  <div class=\"card\">\n    <img class=\"card-img\" src=\"https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=600&auto=format&fit=crop&q=80\" alt=\"Cyberpunk Abstract\">\n    <span class=\"tag\">NFT #8820</span>\n    <h3>Cybernetic Nexus</h3>\n    <p>High-dimensional algorithmic artifact generated in real-time neural clusters.</p>\n    <div class=\"card-footer\">\n      <div class=\"author\">\n        <img class=\"author-img\" src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80\" alt=\"Avatar\">\n        <span>Aura.eth</span>\n      </div>\n      <div class=\"price\">2.45 ETH</div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card2.html", "title": "Frosted Glassmorphism Card", "description": "Ultra-modern translucent glass card featuring blurred backdrop, specular lighting, and soft shadows.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Frosted Glassmorphism Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: radial-gradient(circle at 10% 20%, #ec4899 0%, #3b82f6 90%); min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n    .glass-card { width: 340px; background: rgba(255, 255, 255, 0.15); border: 1px solid rgba(255, 255, 255, 0.35); border-radius: 24px; padding: 28px 24px; backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); box-shadow: 0 20px 40px rgba(0,0,0,0.2); color: white; transition: transform 0.3s ease; }\n    .glass-card:hover { transform: translateY(-6px); }\n    .icon-box { width: 52px; height: 52px; border-radius: 16px; background: rgba(255,255,255,0.25); display: grid; place-items: center; font-size: 24px; margin-bottom: 20px; border: 1px solid rgba(255,255,255,0.4); }\n    h3 { font-size: 1.35rem; font-weight: 700; margin-bottom: 10px; }\n    p { font-size: 0.9rem; line-height: 1.6; opacity: 0.85; margin-bottom: 24px; }\n    .btn-glass { width: 100%; padding: 12px; background: rgba(255,255,255,0.9); color: #0f172a; border: none; border-radius: 12px; font-weight: 700; cursor: pointer; transition: background 0.2s; font-size: 0.9rem; }\n    .btn-glass:hover { background: #ffffff; }\n  </style>\n</head>\n<body>\n  <div class=\"glass-card\">\n    <div class=\"icon-box\">\ud83d\udc8e</div>\n    <h3>Glass Interface</h3>\n    <p>Crafted with modern backdrop filters, semi-transparent layers, and polished borders.</p>\n    <button class=\"btn-glass\">Explore Concept</button>\n  </div>\n</body>\n</html>"}, {"filename": "card3.html", "title": "Neumorphism Soft UI Card", "description": "Refined tactile dark neumorphic card with dual inner/outer extrusion shadows and soft press response.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Neumorphism Soft UI Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #1e2430; min-height: 100vh; display: grid; place-items: center; }\n    .neu-card { width: 320px; background: #1e2430; border-radius: 28px; padding: 28px; box-shadow: 12px 12px 24px #141820, -12px -12px 24px #283040; text-align: center; }\n    .neu-avatar { width: 88px; height: 88px; border-radius: 50%; margin: 0 auto 16px; padding: 5px; box-shadow: inset 4px 4px 8px #141820, inset -4px -4px 8px #283040; }\n    .neu-avatar img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; }\n    h3 { color: #e2e8f0; font-size: 1.2rem; margin-bottom: 4px; }\n    .role { color: #38bdf8; font-size: 0.8rem; font-weight: 600; text-transform: uppercase; margin-bottom: 14px; }\n    p { color: #94a3b8; font-size: 0.85rem; line-height: 1.5; margin-bottom: 22px; }\n    .neu-btn { width: 100%; padding: 12px; background: #1e2430; color: #38bdf8; border: none; border-radius: 14px; font-weight: 700; cursor: pointer; box-shadow: 5px 5px 12px #141820, -5px -5px 12px #283040; transition: all 0.2s; }\n    .neu-btn:active { box-shadow: inset 4px 4px 8px #141820, inset -4px -4px 8px #283040; }\n  </style>\n</head>\n<body>\n  <div class=\"neu-card\">\n    <div class=\"neu-avatar\">\n      <img src=\"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80\" alt=\"Person\">\n    </div>\n    <h3>Julian Vance</h3>\n    <div class=\"role\">Lead AI Engineer</div>\n    <p>Architecting multi-modal neural systems with zero-latency inference workflows.</p>\n    <button class=\"neu-btn\">Connect Profile</button>\n  </div>\n</body>\n</html>"}, {"filename": "card4.html", "title": "Monochrome Luxury Editorial Card", "description": "High-fashion typographic editorial card with high-contrast monochrome design and clean dividers.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Monochrome Editorial Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,400&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Inter', sans-serif; background: #000; min-height: 100vh; display: grid; place-items: center; padding: 20px; }\n    .editorial-card { width: 340px; background: #0a0a0a; border: 1px solid #222; border-radius: 4px; padding: 24px; color: #fff; transition: border-color 0.3s; }\n    .editorial-card:hover { border-color: #fff; }\n    .num { font-size: 0.75rem; letter-spacing: 2px; color: #666; margin-bottom: 12px; }\n    .photo { width: 100%; height: 210px; object-fit: cover; filter: grayscale(100%); transition: filter 0.4s; margin-bottom: 18px; }\n    .editorial-card:hover .photo { filter: grayscale(0%); }\n    h3 { font-family: 'Playfair Display', serif; font-size: 1.4rem; font-style: italic; margin-bottom: 8px; font-weight: 600; }\n    p { font-size: 0.85rem; color: #888; line-height: 1.6; margin-bottom: 18px; }\n    .read-link { font-size: 0.75rem; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase; color: #fff; text-decoration: none; border-bottom: 1px solid #fff; padding-bottom: 2px; }\n  </style>\n</head>\n<body>\n  <div class=\"editorial-card\">\n    <div class=\"num\">N\u00b0 04 / ARCHITECTURE</div>\n    <img class=\"photo\" src=\"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?w=600&auto=format&fit=crop&q=80\" alt=\"Architecture\">\n    <h3>The Quiet Geometry</h3>\n    <p>Exploring silent brutalism and negative space in contemporary Scandinavian shelters.</p>\n    <a href=\"#\" class=\"read-link\">Read Story &rarr;</a>\n  </div>\n</body>\n</html>"}, {"filename": "card5.html", "title": "Animated Gradient Border Card", "description": "Rotating mesh gradient border card with glossy inner fill and interactive hover glow effects.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Animated Gradient Border Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c0f17; min-height: 100vh; display: grid; place-items: center; }\n    .outer-wrapper { position: relative; width: 330px; border-radius: 20px; padding: 2px; background: linear-gradient(135deg, #f43f5e, #8b5cf6, #06b6d4); overflow: hidden; }\n    .outer-wrapper::before { content: ''; position: absolute; inset: -50%; background: conic-gradient(from 0deg, #f43f5e, #8b5cf6, #06b6d4, #f43f5e); animation: rotate 4s linear infinite; }\n    @keyframes rotate { 100% { transform: rotate(360deg); } }\n    .inner-card { position: relative; background: #111827; border-radius: 18px; padding: 28px 24px; z-index: 1; }\n    .badge { background: rgba(244,63,94,0.15); color: #fb7185; font-size: 0.75rem; font-weight: 700; padding: 4px 10px; border-radius: 6px; display: inline-block; margin-bottom: 14px; }\n    h3 { color: #fff; font-size: 1.25rem; font-weight: 800; margin-bottom: 8px; }\n    p { color: #94a3b8; font-size: 0.88rem; line-height: 1.5; margin-bottom: 20px; }\n    .btn-gradient { width: 100%; padding: 11px; background: linear-gradient(135deg, #f43f5e, #8b5cf6); color: #fff; border: none; border-radius: 10px; font-weight: 700; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"outer-wrapper\">\n    <div class=\"inner-card\">\n      <span class=\"badge\">\ud83d\udd25 Hot Release</span>\n      <h3>Reactive Motion</h3>\n      <p>Fluid keyframe animations and GPU-accelerated gradients designed for next-gen web apps.</p>\n      <button class=\"btn-gradient\">Get Started</button>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card6.html", "title": "Sneaker Product Showcase Card", "description": "High-energy sneaker e-commerce card with floating angle shoe, size selector, and add to cart button.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Sneaker Product Showcase Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0f172a; min-height: 100vh; display: grid; place-items: center; }\n    .product-card { width: 330px; background: #1e293b; border: 1px solid #334155; border-radius: 20px; padding: 22px; position: relative; overflow: hidden; }\n    .img-wrap { width: 100%; height: 180px; background: radial-gradient(circle, #334155, #1e293b); border-radius: 14px; display: grid; place-items: center; margin-bottom: 16px; overflow: hidden; }\n    .product-img { width: 85%; transform: rotate(-15deg); transition: transform 0.4s ease; filter: drop-shadow(0 15px 15px rgba(0,0,0,0.6)); }\n    .product-card:hover .product-img { transform: rotate(0deg) scale(1.08); }\n    .cat { color: #38bdf8; font-size: 0.75rem; font-weight: 700; text-transform: uppercase; margin-bottom: 4px; }\n    h3 { color: #f8fafc; font-size: 1.25rem; font-weight: 800; margin-bottom: 6px; }\n    .price { color: #fff; font-size: 1.25rem; font-weight: 800; margin-bottom: 16px; }\n    .sizes { display: flex; gap: 8px; margin-bottom: 18px; }\n    .size-btn { width: 34px; height: 34px; border-radius: 8px; background: #0f172a; border: 1px solid #334155; color: #cbd5e1; font-weight: 700; font-size: 0.8rem; cursor: pointer; }\n    .size-btn.active { background: #38bdf8; color: #000; border-color: #38bdf8; }\n    .btn-cart { width: 100%; padding: 12px; background: #38bdf8; color: #000; font-weight: 800; border: none; border-radius: 10px; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"product-card\">\n    <div class=\"img-wrap\">\n      <img class=\"product-img\" src=\"https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=500&auto=format&fit=crop&q=80\" alt=\"Sneaker\">\n    </div>\n    <div class=\"cat\">Running Footwear</div>\n    <h3>Air Sonic React</h3>\n    <div class=\"price\">$159.00</div>\n    <div class=\"sizes\">\n      <button class=\"size-btn\">40</button>\n      <button class=\"size-btn active\">41</button>\n      <button class=\"size-btn\">42</button>\n      <button class=\"size-btn\">43</button>\n    </div>\n    <button class=\"btn-cart\">Add to Cart</button>\n  </div>\n</body>\n</html>"}, {"filename": "card7.html", "title": "SaaS Pricing Tier Card", "description": "Eye-catching enterprise subscription card with glowing badges, checklist benefits, and CTA.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>SaaS Pricing Tier Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #090e17; min-height: 100vh; display: grid; place-items: center; }\n    .pricing-card { width: 330px; background: linear-gradient(180deg, #131b2e, #0c121e); border: 2px solid #6366f1; border-radius: 22px; padding: 32px 26px; box-shadow: 0 10px 40px rgba(99,102,241,0.2); position: relative; }\n    .badge { position: absolute; top: -14px; left: 50%; transform: translateX(-50%); background: #6366f1; color: white; font-weight: 800; font-size: 0.72rem; text-transform: uppercase; padding: 4px 14px; border-radius: 20px; }\n    h4 { color: #f8fafc; font-size: 1.2rem; font-weight: 700; margin-bottom: 6px; }\n    .desc { color: #94a3b8; font-size: 0.8rem; margin-bottom: 20px; }\n    .price { font-size: 2.2rem; font-weight: 800; color: #fff; margin-bottom: 20px; }\n    .price span { font-size: 0.85rem; color: #94a3b8; font-weight: 500; }\n    .features { list-style: none; margin-bottom: 24px; }\n    .features li { color: #cbd5e1; font-size: 0.85rem; margin-bottom: 10px; display: flex; align-items: center; gap: 8px; }\n    .features li::before { content: '\u2713'; color: #818cf8; font-weight: 800; }\n    .btn-plan { width: 100%; padding: 12px; background: #6366f1; color: white; border: none; border-radius: 10px; font-weight: 700; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"pricing-card\">\n    <span class=\"badge\">Most Popular</span>\n    <h4>Enterprise Growth</h4>\n    <div class=\"desc\">For scaling engineering orgs</div>\n    <div class=\"price\">$79 <span>/ month</span></div>\n    <ul class=\"features\">\n      <li>Unlimited Multi-Agent Swarms</li>\n      <li>99.99% Uptime Guarantee</li>\n      <li>Dedicated Solution Architect</li>\n      <li>Custom SSO & Security Audits</li>\n    </ul>\n    <button class=\"btn-plan\">Upgrade to Pro</button>\n  </div>\n</body>\n</html>"}, {"filename": "card8.html", "title": "Audio Visualizer & Music Player Card", "description": "Modern Spotify-style music card with album disc art, scrubber bar, and media controls.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Music Player Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #07090e; min-height: 100vh; display: grid; place-items: center; }\n    .player-card { width: 320px; background: #121826; border: 1px solid #222d42; border-radius: 24px; padding: 24px; text-align: center; }\n    .cover-art { width: 160px; height: 160px; border-radius: 50%; object-fit: cover; margin: 0 auto 18px; border: 4px solid #1e293b; box-shadow: 0 10px 25px rgba(0,0,0,0.6); animation: spin 16s linear infinite; }\n    @keyframes spin { 100% { transform: rotate(360deg); } }\n    h3 { color: #f8fafc; font-size: 1.15rem; margin-bottom: 4px; }\n    .artist { color: #94a3b8; font-size: 0.85rem; margin-bottom: 20px; }\n    .progress-bar { width: 100%; height: 5px; background: #26334a; border-radius: 10px; margin-bottom: 8px; position: relative; }\n    .progress-fill { width: 45%; height: 100%; background: #10b981; border-radius: 10px; }\n    .time-row { display: flex; justify-content: space-between; color: #64748b; font-size: 0.75rem; margin-bottom: 18px; }\n    .controls { display: flex; justify-content: center; align-items: center; gap: 20px; font-size: 20px; color: #cbd5e1; }\n    .play-btn { width: 46px; height: 46px; border-radius: 50%; background: #10b981; color: white; display: grid; place-items: center; font-size: 18px; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"player-card\">\n    <img class=\"cover-art\" src=\"https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?w=400&auto=format&fit=crop&q=80\" alt=\"Album Cover\">\n    <h3>Midnight Echoes</h3>\n    <div class=\"artist\">Synthwave Collective</div>\n    <div class=\"progress-bar\"><div class=\"progress-fill\"></div></div>\n    <div class=\"time-row\"><span>1:42</span><span>3:50</span></div>\n    <div class=\"controls\">\n      <span>\u23ee</span>\n      <div class=\"play-btn\">\u25b6</div>\n      <span>\u23ed</span>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card9.html", "title": "Crypto Wallet Balance & Token Card", "description": "Web3 crypto token card with dynamic sparkline graph simulation, current balance, and quick actions.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Crypto Asset Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&family=JetBrains+Mono:wght@600&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c0f17; min-height: 100vh; display: grid; place-items: center; }\n    .crypto-card { width: 340px; background: linear-gradient(135deg, #1e1b4b, #0f172a); border: 1px solid #312e81; border-radius: 20px; padding: 26px; color: white; }\n    .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }\n    .coin-badge { display: flex; align-items: center; gap: 8px; font-weight: 700; }\n    .coin-icon { width: 34px; height: 34px; background: #6366f1; border-radius: 50%; display: grid; place-items: center; font-size: 18px; }\n    .change { font-family: 'JetBrains Mono', monospace; color: #10b981; font-size: 0.82rem; background: rgba(16,185,129,0.15); padding: 4px 8px; border-radius: 6px; }\n    .balance-label { font-size: 0.78rem; color: #94a3b8; margin-bottom: 4px; }\n    .balance-val { font-family: 'JetBrains Mono', monospace; font-size: 1.8rem; font-weight: 800; margin-bottom: 20px; }\n    .actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n    .btn-act { padding: 10px; background: #312e81; border: none; border-radius: 8px; color: white; font-weight: 700; font-size: 0.85rem; cursor: pointer; }\n    .btn-act.primary { background: #6366f1; }\n  </style>\n</head>\n<body>\n  <div class=\"crypto-card\">\n    <div class=\"header\">\n      <div class=\"coin-badge\">\n        <div class=\"coin-icon\">\u039e</div>\n        <span>Ethereum</span>\n      </div>\n      <span class=\"change\">+14.28%</span>\n    </div>\n    <div class=\"balance-label\">Total Portfolio Balance</div>\n    <div class=\"balance-val\">$48,290.50</div>\n    <div class=\"actions\">\n      <button class=\"btn-act primary\">Send</button>\n      <button class=\"btn-act\">Receive</button>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card10.html", "title": "Social Creator Profile Card", "description": "Creator bio card with background cover banner, overlapping avatar, follower metrics, and follow CTA.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Social Creator Profile Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c1017; min-height: 100vh; display: grid; place-items: center; }\n    .profile-card { width: 330px; background: #161e2e; border: 1px solid #283750; border-radius: 20px; overflow: hidden; text-align: center; }\n    .banner { height: 100px; background: linear-gradient(135deg, #ec4899, #8b5cf6); }\n    .avatar-wrap { margin-top: -45px; margin-bottom: 12px; }\n    .avatar { width: 84px; height: 84px; border-radius: 50%; border: 4px solid #161e2e; object-fit: cover; }\n    h3 { color: #f8fafc; font-size: 1.25rem; font-weight: 800; }\n    .handle { color: #94a3b8; font-size: 0.8rem; margin-bottom: 14px; }\n    .stats { display: flex; justify-content: space-around; padding: 14px 0; border-top: 1px solid #25334c; border-bottom: 1px solid #25334c; margin-bottom: 18px; }\n    .stat-num { color: white; font-weight: 800; font-size: 1rem; }\n    .stat-label { color: #64748b; font-size: 0.72rem; text-transform: uppercase; }\n    .btn-follow { width: calc(100% - 40px); margin: 0 auto 20px; padding: 11px; background: #8b5cf6; color: white; font-weight: 700; border: none; border-radius: 10px; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"profile-card\">\n    <div class=\"banner\"></div>\n    <div class=\"avatar-wrap\">\n      <img class=\"avatar\" src=\"https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=200&auto=format&fit=crop&q=80\" alt=\"Avatar\">\n    </div>\n    <h3>Elena Rostova</h3>\n    <div class=\"handle\">@elena_creates</div>\n    <div class=\"stats\">\n      <div><div class=\"stat-num\">142K</div><div class=\"stat-label\">Followers</div></div>\n      <div><div class=\"stat-num\">890</div><div class=\"stat-label\">Following</div></div>\n      <div><div class=\"stat-num\">2.4M</div><div class=\"stat-label\">Likes</div></div>\n    </div>\n    <button class=\"btn-follow\">Follow Creator</button>\n  </div>\n</body>\n</html>"}, {"filename": "card11.html", "title": "Apple-Style Bento Feature Card", "description": "Subtle grid lines, high-contrast typography, and crisp isometric data metrics.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Bento Grid Feature Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #000; min-height: 100vh; display: grid; place-items: center; }\n    .bento-card { width: 340px; background: #0f0f11; border: 1px solid #222226; border-radius: 22px; padding: 28px; color: white; position: relative; overflow: hidden; }\n    .bento-tag { font-size: 0.75rem; color: #a1a1aa; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 10px; font-weight: 700; }\n    h3 { font-size: 1.4rem; font-weight: 800; margin-bottom: 8px; line-height: 1.3; }\n    p { color: #71717a; font-size: 0.88rem; line-height: 1.5; margin-bottom: 24px; }\n    .metric-badge { background: #18181b; border: 1px solid #27272a; border-radius: 12px; padding: 14px 18px; display: flex; justify-content: space-between; align-items: center; }\n    .metric-num { font-size: 1.8rem; font-weight: 800; color: #fff; }\n    .metric-sub { color: #10b981; font-size: 0.8rem; font-weight: 600; }\n  </style>\n</head>\n<body>\n  <div class=\"bento-card\">\n    <div class=\"bento-tag\">Performance</div>\n    <h3>Sub-millisecond Edge Latency</h3>\n    <p>Routed automatically through our global mesh of 310+ edge locations.</p>\n    <div class=\"metric-badge\">\n      <div>\n        <div class=\"metric-num\">14ms</div>\n        <span style=\"font-size: 0.72rem; color: #71717a;\">Avg Global Ping</span>\n      </div>\n      <div class=\"metric-sub\">&uarr; 3.2x Faster</div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card12.html", "title": "Gourmet Food & Recipe Card", "description": "Appetizing culinary food card with cooking duration badges, caloric metrics, and rating star.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Gourmet Food Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c1017; min-height: 100vh; display: grid; place-items: center; }\n    .food-card { width: 330px; background: #161e2e; border: 1px solid #283750; border-radius: 20px; overflow: hidden; position: relative; }\n    .food-img { width: 100%; height: 200px; object-fit: cover; }\n    .rating-badge { position: absolute; top: 14px; right: 14px; background: rgba(0,0,0,0.7); backdrop-filter: blur(8px); color: #fbbf24; font-size: 0.8rem; font-weight: 700; padding: 4px 10px; border-radius: 20px; }\n    .content { padding: 22px; }\n    h3 { color: #f8fafc; font-size: 1.25rem; font-weight: 800; margin-bottom: 8px; }\n    .meta { display: flex; gap: 14px; color: #94a3b8; font-size: 0.82rem; margin-bottom: 18px; }\n    .footer { display: flex; justify-content: space-between; align-items: center; }\n    .price { font-size: 1.3rem; font-weight: 800; color: #10b981; }\n    .btn-order { padding: 9px 18px; background: #f97316; color: white; border: none; border-radius: 8px; font-weight: 700; cursor: pointer; }\n  </style>\n</head>\n<body>\n  <div class=\"food-card\">\n    <img class=\"food-img\" src=\"https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=600&auto=format&fit=crop&q=80\" alt=\"Avocado Salad\">\n    <div class=\"rating-badge\">\u2605 4.9 (320)</div>\n    <div class=\"content\">\n      <h3>Mediterranean Bowl</h3>\n      <div class=\"meta\">\n        <span>\u23f1 15 Mins</span>\n        <span>\ud83d\udd25 420 kcal</span>\n      </div>\n      <div class=\"footer\">\n        <div class=\"price\">$14.50</div>\n        <button class=\"btn-order\">Order Now</button>\n      </div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card13.html", "title": "Fitness Health & Activity Ring Card", "description": "Apple Watch style activity tracker card with circular progress indicators, calories, and goals.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Fitness Activity Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #000; min-height: 100vh; display: grid; place-items: center; }\n    .fit-card { width: 320px; background: #121216; border: 1px solid #23232b; border-radius: 22px; padding: 24px; color: white; }\n    .top { display: flex; justify-content: space-between; margin-bottom: 18px; }\n    h3 { font-size: 1.15rem; font-weight: 700; }\n    .date { color: #71717a; font-size: 0.8rem; }\n    .rings-area { display: flex; align-items: center; gap: 18px; margin-bottom: 20px; }\n    .stats-col { flex: 1; }\n    .stat-row { margin-bottom: 10px; }\n    .stat-val { font-size: 1.1rem; font-weight: 800; }\n    .stat-lbl { font-size: 0.72rem; text-transform: uppercase; color: #a1a1aa; }\n    .val-move { color: #fa243c; }\n    .val-exercise { color: #a2fa24; }\n    .val-stand { color: #24d6fa; }\n  </style>\n</head>\n<body>\n  <div class=\"fit-card\">\n    <div class=\"top\">\n      <h3>Today's Activity</h3>\n      <span class=\"date\">Nov 23</span>\n    </div>\n    <div class=\"rings-area\">\n      <div style=\"font-size: 42px;\">\ud83c\udfaf</div>\n      <div class=\"stats-col\">\n        <div class=\"stat-row\"><div class=\"stat-val val-move\">580 / 600 CAL</div><div class=\"stat-lbl\">Move</div></div>\n        <div class=\"stat-row\"><div class=\"stat-val val-exercise\">42 / 30 MIN</div><div class=\"stat-lbl\">Exercise</div></div>\n        <div class=\"stat-row\"><div class=\"stat-val val-stand\">11 / 12 HRS</div><div class=\"stat-lbl\">Stand</div></div>\n      </div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card14.html", "title": "Luxury Real Estate Villa Card", "description": "Real estate property card with bedroom/bathroom icon counters, location pin, and virtual tour tag.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Real Estate Property Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c1017; min-height: 100vh; display: grid; place-items: center; }\n    .property-card { width: 340px; background: #161e2e; border: 1px solid #283750; border-radius: 20px; overflow: hidden; }\n    .thumb { width: 100%; height: 200px; object-fit: cover; }\n    .body { padding: 22px; }\n    .price-tag { color: #38bdf8; font-size: 1.4rem; font-weight: 800; margin-bottom: 6px; }\n    h3 { color: #f8fafc; font-size: 1.15rem; margin-bottom: 6px; }\n    .loc { color: #94a3b8; font-size: 0.8rem; margin-bottom: 16px; }\n    .specs { display: flex; justify-content: space-between; border-top: 1px solid #233148; padding-top: 14px; color: #cbd5e1; font-size: 0.82rem; }\n  </style>\n</head>\n<body>\n  <div class=\"property-card\">\n    <img class=\"thumb\" src=\"https://images.unsplash.com/photo-1613977257363-707ba9348227?w=600&auto=format&fit=crop&q=80\" alt=\"Villa\">\n    <div class=\"body\">\n      <div class=\"price-tag\">$1,450,000</div>\n      <h3>The Glass Pavilion</h3>\n      <div class=\"loc\">\ud83d\udccd Beverly Hills, California</div>\n      <div class=\"specs\">\n        <span>\ud83d\udecf 4 Beds</span>\n        <span>\ud83d\udebf 3 Baths</span>\n        <span>\ud83d\udcd0 3,800 sqft</span>\n      </div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card15.html", "title": "Agile Kanban Project Task Card", "description": "Project management ticket card with priority tag, assignee avatars, checklist progress bar.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Kanban Project Task Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c0f17; min-height: 100vh; display: grid; place-items: center; }\n    .task-card { width: 320px; background: #161e2e; border: 1px solid #283750; border-radius: 16px; padding: 20px; }\n    .top-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }\n    .badge-urgent { background: rgba(239,68,68,0.15); color: #f87171; font-size: 0.72rem; font-weight: 700; padding: 3px 10px; border-radius: 6px; }\n    h4 { color: #f8fafc; font-size: 1rem; margin-bottom: 8px; line-height: 1.4; }\n    p { color: #94a3b8; font-size: 0.8rem; line-height: 1.5; margin-bottom: 16px; }\n    .bar { height: 6px; background: #26334a; border-radius: 10px; overflow: hidden; margin-bottom: 16px; }\n    .fill { width: 75%; height: 100%; background: #6366f1; border-radius: 10px; }\n    .footer { display: flex; justify-content: space-between; align-items: center; color: #94a3b8; font-size: 0.78rem; }\n    .avatars img { width: 26px; height: 26px; border-radius: 50%; border: 2px solid #161e2e; margin-left: -6px; }\n  </style>\n</head>\n<body>\n  <div class=\"task-card\">\n    <div class=\"top-row\">\n      <span class=\"badge-urgent\">High Priority</span>\n      <span style=\"color: #64748b; font-size: 0.8rem;\">ENG-204</span>\n    </div>\n    <h4>Deploy Multi-Agent Orchestrator</h4>\n    <p>Wire up WebSocket channels and real-time response stream hooks.</p>\n    <div class=\"bar\"><div class=\"fill\"></div></div>\n    <div class=\"footer\">\n      <span>Due Tomorrow</span>\n      <div class=\"avatars\">\n        <img src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80\" alt=\"User\">\n        <img src=\"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100&auto=format&fit=crop&q=80\" alt=\"User\">\n      </div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card16.html", "title": "Tech Conference Pass & Ticket Card", "description": "Perforated boarding pass / VIP summit ticket card with barcode and seat details.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Conference Ticket Pass Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@700;800&family=JetBrains+Mono:wght@600&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #07090e; min-height: 100vh; display: grid; place-items: center; }\n    .ticket { width: 320px; background: #161e2e; border: 1px solid #283750; border-radius: 20px; overflow: hidden; position: relative; }\n    .ticket-head { background: linear-gradient(135deg, #3b82f6, #8b5cf6); padding: 20px; color: white; }\n    .event-type { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; opacity: 0.8; }\n    h3 { font-size: 1.3rem; font-weight: 800; margin-top: 4px; }\n    .ticket-body { padding: 22px; color: white; }\n    .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 20px; }\n    .lbl { font-size: 0.72rem; color: #94a3b8; text-transform: uppercase; }\n    .val { font-size: 0.95rem; font-weight: 700; }\n    .barcode { font-family: 'JetBrains Mono', monospace; letter-spacing: 5px; text-align: center; color: #64748b; font-size: 0.9rem; padding-top: 14px; border-top: 2px dashed #243147; }\n  </style>\n</head>\n<body>\n  <div class=\"ticket\">\n    <div class=\"ticket-head\">\n      <div class=\"event-type\">VIP Access Pass</div>\n      <h3>AI SUMMIT 2026</h3>\n    </div>\n    <div class=\"ticket-body\">\n      <div class=\"grid\">\n        <div><div class=\"lbl\">Date</div><div class=\"val\">Nov 28, 2026</div></div>\n        <div><div class=\"lbl\">Location</div><div class=\"val\">San Francisco</div></div>\n        <div><div class=\"lbl\">Attendee</div><div class=\"val\">Alex Morgan</div></div>\n        <div><div class=\"lbl\">Seat</div><div class=\"val\">A-14 (Front)</div></div>\n      </div>\n      <div class=\"barcode\">||| | |||| | ||| |||| |</div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card17.html", "title": "Dynamic Atmospheric Weather Card", "description": "Sleek sky gradient card with high-temp display, weather conditions, wind speed, and humidity.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Atmospheric Weather Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c1017; min-height: 100vh; display: grid; place-items: center; }\n    .weather-card { width: 320px; background: linear-gradient(180deg, #1e3a8a, #0f172a); border: 1px solid #2563eb; border-radius: 24px; padding: 26px; color: white; text-align: center; }\n    .city { font-size: 1.25rem; font-weight: 700; margin-bottom: 4px; }\n    .condition { color: #93c5fd; font-size: 0.85rem; margin-bottom: 16px; }\n    .icon { font-size: 48px; margin-bottom: 8px; }\n    .temp { font-size: 3rem; font-weight: 800; margin-bottom: 16px; }\n    .details { display: flex; justify-content: space-around; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 14px; font-size: 0.82rem; color: #cbd5e1; }\n  </style>\n</head>\n<body>\n  <div class=\"weather-card\">\n    <div class=\"city\">Tokyo, Japan</div>\n    <div class=\"condition\">Scattered Rain & Thunder</div>\n    <div class=\"icon\">\u26c8\ufe0f</div>\n    <div class=\"temp\">18\u00b0C</div>\n    <div class=\"details\">\n      <div>\ud83d\udca7 84% Hum</div>\n      <div>\ud83d\udca8 14 km/h Wind</div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card18.html", "title": "Verified Customer Testimonial Card", "description": "Trustworthy quote card with company logo, star badges, user portrait, and quote typography.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Customer Testimonial Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #0c0f17; min-height: 100vh; display: grid; place-items: center; }\n    .quote-card { width: 340px; background: #161e2e; border: 1px solid #283750; border-radius: 20px; padding: 28px; }\n    .stars { color: #fbbf24; font-size: 16px; margin-bottom: 14px; }\n    p { color: #e2e8f0; font-size: 0.95rem; line-height: 1.6; margin-bottom: 22px; font-style: italic; }\n    .person { display: flex; align-items: center; gap: 12px; }\n    .avatar { width: 44px; height: 44px; border-radius: 50%; object-fit: cover; }\n    .name { color: #fff; font-weight: 700; font-size: 0.95rem; }\n    .title { color: #94a3b8; font-size: 0.78rem; }\n  </style>\n</head>\n<body>\n  <div class=\"quote-card\">\n    <div class=\"stars\">\u2605\u2605\u2605\u2605\u2605</div>\n    <p>\"Antigravity accelerated our frontend prototyping by 10x. The component designs are breathtaking right out of the box.\"</p>\n    <div class=\"person\">\n      <img class=\"avatar\" src=\"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100&auto=format&fit=crop&q=80\" alt=\"Sarah Chen\">\n      <div>\n        <div class=\"name\">Sarah Chen</div>\n        <div class=\"title\">VP of Product at ScaleUp</div>\n      </div>\n    </div>\n  </div>\n</body>\n</html>"}, {"filename": "card19.html", "title": "Gamified Level & Achievement Card", "description": "Gamer XP tier card with 3D trophy badge, XP progress bar, unlocked rewards, and glowing shield.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Achievement Badge Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@700;800&family=JetBrains+Mono:wght@600&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'Plus Jakarta Sans', sans-serif; background: #07090e; min-height: 100vh; display: grid; place-items: center; }\n    .badge-card { width: 320px; background: radial-gradient(circle at 50% 0%, #312e81, #0f172a); border: 1px solid #4338ca; border-radius: 22px; padding: 26px; text-align: center; color: white; }\n    .trophy { font-size: 52px; margin-bottom: 12px; filter: drop-shadow(0 10px 15px rgba(245,158,11,0.4)); }\n    .tier { color: #fbbf24; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 4px; }\n    h3 { font-size: 1.3rem; font-weight: 800; margin-bottom: 6px; }\n    p { color: #94a3b8; font-size: 0.82rem; margin-bottom: 20px; }\n    .xp-bar { height: 8px; background: #1e293b; border-radius: 10px; overflow: hidden; margin-bottom: 8px; }\n    .xp-fill { width: 85%; height: 100%; background: linear-gradient(90deg, #f59e0b, #fbbf24); }\n    .xp-text { font-family: 'JetBrains Mono', monospace; font-size: 0.75rem; color: #cbd5e1; }\n  </style>\n</head>\n<body>\n  <div class=\"badge-card\">\n    <div class=\"trophy\">\ud83c\udfc6</div>\n    <div class=\"tier\">Tier 10 Master</div>\n    <h3>Grand Architect</h3>\n    <p>Completed 100+ production agent workflows with flawless test coverage.</p>\n    <div class=\"xp-bar\"><div class=\"xp-fill\"></div></div>\n    <div class=\"xp-text\">8,500 / 10,000 XP</div>\n  </div>\n</body>\n</html>"}, {"filename": "card20.html", "title": "Developer Terminal & Syntax Card", "description": "MacOS-style developer terminal card with traffic light dots, copy button, and code syntax highlighting.", "code": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Developer Terminal Card</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@500;700&family=Plus+Jakarta+Sans:wght@600&display=swap\" rel=\"stylesheet\">\n  <style>\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n    body { font-family: 'JetBrains Mono', monospace; background: #0c0f17; min-height: 100vh; display: grid; place-items: center; }\n    .term-card { width: 340px; background: #090d16; border: 1px solid #1e293b; border-radius: 16px; overflow: hidden; }\n    .term-head { padding: 12px 16px; background: #111827; border-bottom: 1px solid #1e293b; display: flex; align-items: center; gap: 6px; }\n    .dot { width: 10px; height: 10px; border-radius: 50%; }\n    .dot.red { background: #ef4444; }\n    .dot.yellow { background: #f59e0b; }\n    .dot.green { background: #10b981; }\n    .term-title { margin-left: 10px; color: #64748b; font-size: 0.72rem; }\n    .term-body { padding: 18px; font-size: 0.8rem; line-height: 1.6; }\n    .kwd { color: #f43f5e; }\n    .fn { color: #38bdf8; }\n    .str { color: #10b981; }\n    .comm { color: #64748b; }\n  </style>\n</head>\n<body>\n  <div class=\"term-card\">\n    <div class=\"term-head\">\n      <div class=\"dot red\"></div>\n      <div class=\"dot yellow\"></div>\n      <div class=\"dot green\"></div>\n      <span class=\"term-title\">agent.ts</span>\n    </div>\n    <div class=\"term-body\">\n      <span class=\"comm\">// Initialize agent</span><br>\n      <span class=\"kwd\">const</span> agent = <span class=\"kwd\">new</span> <span class=\"fn\">AIAgent</span>({<br>\n      &nbsp;&nbsp;model: <span class=\"str\">'gemini-pro'</span>,<br>\n      &nbsp;&nbsp;speed: <span class=\"str\">'realtime'</span><br>\n      });<br><br>\n      <span class=\"kwd\">await</span> agent.<span class=\"fn\">orchestrate</span>();\n    </div>\n  </div>\n</body>\n</html>"}];